  import { blogContent } from "./blog-content-i18n";
  const C: Record<string, Partial<Record<BlogLang, any[]>>> = blogContent as any;

  export function getBlogTranslation(
    slug: string,
    lang: string,
  ): { title?: string; excerpt?: string; content?: any[] } {
    const entry = T[slug];
    if (!entry) return {};
    const l = lang as BlogLang;
    const tr = entry[l];
    if (!tr) return {};
    const cEntry = C[slug];
    const content = cEntry?.[l];
    return { title: tr.t, excerpt: tr.e, content };
  }
  